// slide-01.js - Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'DiaTool-DPO: Multi-Turn DPO for Tool-Augmented LLMs'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.15,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("DiaTool-DPO", {
    x: 0.5, y: 1.6, w: 9, h: 1.0,
    fontSize: 60, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center"
  });

  // Subtitle
  slide.addText("Enhancing Tool-Augmented LLM Dialogue\nvia Direct Preference Optimization", {
    x: 0.5, y: 2.7, w: 9, h: 1.0,
    fontSize: 26, fontFace: "Calibri",
    color: theme.light, align: "center"
  });

  // Tagline
  slide.addText("A novel DPO-based method that models TA-LLM interactions as an MDP\nwith 5 dialogue states and 3 query types", {
    x: 0.5, y: 4.0, w: 9, h: 0.8,
    fontSize: 14, fontFace: "Calibri",
    color: theme.accent, align: "center", italic: true
  });

  // Bottom decorative bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.475, w: 10, h: 0.15,
    fill: { color: theme.accent }
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "f8fafc"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

