// slide-02.js - Problem & Motivation: SFT Failure Modes
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'SFT Alone Fails to Teach Slot-Filling and Tool Rejection'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("SFT Alone Fails to Teach Slot-Filling and Tool Rejection", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Subtitle/intro
  slide.addText("TA-LLMs trained only with SFT struggle with incomplete queries and out-of-scope requests", {
    x: 0.5, y: 0.95, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Three failure mode cards
  const cardY = 1.6;
  const cardH = 2.8;
  const cardW = 2.9;
  const gap = 0.15;

  // Card 1: Failing to ask follow-up questions
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: cardW, h: cardH,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: cardW, h: 0.08,
    fill: { color: theme.accent }
  });
  slide.addText("1", {
    x: 0.7, y: cardY + 0.25, w: 0.4, h: 0.4,
    fontSize: 20, fontFace: "Georgia",
    color: theme.accent, bold: true
  });
  slide.addText("Missing Follow-Up", {
    x: 1.1, y: cardY + 0.25, w: 2.1, h: 0.4,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true
  });
  slide.addText("Failing to ask follow-up questions for missing information leads to incomplete tool calls.", {
    x: 0.7, y: cardY + 0.8, w: 2.5, h: 1.8,
    fontSize: 13, fontFace: "Calibri",
