// slide-03.js - Five-State MDP Formulation
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'Modeling TA-LLM Dialogue as a 5-State Markov Decision Process'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Modeling TA-LLM Dialogue as a 5-State Markov Decision Process", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("The authors model TA-LLM interactions as an MDP with 5 internal (unobserved) states", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // State boxes - arranged horizontally with arrows
  const stateY = 1.7;
  const boxW = 1.6;
  const boxH = 0.9;
  const startX = 0.5;
  const gap = 0.35;

  const states = [
    { num: "1", name: "Initial", desc: "No history" },
    { num: "2", name: "Tool Selected\nw/o Slots", desc: "Params missing" },
    { num: "3", name: "Tool Selected\nw/ Slots", desc: "Args complete" },
    { num: "4", name: "Wait for\nTool Response", desc: "Awaiting results" },
    { num: "5", name: "Complete", desc: "Response ready" }
  ];

  states.forEach((state, i) => {
    const x = startX + i * (boxW + gap);

    // State box
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: stateY, w: boxW, h: boxH,
      fill: { color: i === 0 ? theme.accent : (i === 4 ? theme.secondary : theme.primary) },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 }
    });

    // State number
    slide.addText(state.num, {
      x: x, y: stateY + 0.08, w: boxW, h: 0.3,
      fontSize: 14, fontFace: "Arial",
      color: "FFFFFF", bold: true, align: "center"
    });

    // State name
    slide.addText(state.name, {
      x: x + 0.05, y: stateY + 0.32, w: boxW - 0.1, h: 0.45,
      fontSize: 10, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    // Arrow between states
    if (i < states.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: x + boxW + 0.02, y: stateY + boxH / 2,
        w: gap - 0.04, h: 0,
        line: { color: theme.secondary, width: 2 }
      });
      // Arrow head
      slide.addText("→", {
        x: x + boxW + gap - 0.2, y: stateY + boxH / 2 - 0.15,
        w: 0.3, h: 0.3,
        fontSize: 16, fontFace: "Arial",
        color: theme.secondary, bold: true
      });
    }
  });

  // State descriptions below
  const descY = 2.85;
  const descBoxW = 1.6;
  const descBoxH = 0.9;
  const descGap = 0.35;

  const descriptions = [
    "Out-of-scope\nrequests return\na rejection",
    "Slot-filling QA\ninteractions\noccur here",
    "Tool and all\nargument values\ndetermined",
    "Tool call\nexecuted,\nawaiting results",
    "Tool results\nreceived,\ncompletion sent"
  ];

  descriptions.forEach((desc, i) => {
    const x = startX + i * (descBoxW + descGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: descY, w: descBoxW, h: descBoxH,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 1 }
    });

    slide.addText(desc, {
      x: x + 0.05, y: descY + 0.05, w: descBoxW - 0.1, h: descBoxH - 0.1,
      fontSize: 9, fontFace: "Calibri",
      color: theme.secondary, align: "center", valign: "middle"
    });
  });

  // Special note for Type 3 trajectory (1→1 loop)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.0, w: 4.2, h: 0.65,
    fill: { color: theme.accent, transparency: 15 }
  });
  slide.addText("Type 3 (Out-of-Scope): 1 → 1 (rejection loop)", {
    x: 0.6, y: 4.08, w: 4, h: 0.25,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: true
  });
  slide.addText("When functionality is unavailable, the model stays in Initial state and returns rejection", {
    x: 0.6, y: 4.35, w: 4, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary
  });

  // Type 1 and Type 2 note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.9, y: 4.0, w: 4.6, h: 0.65,
    fill: { color: theme.secondary, transparency: 15 }
  });
  slide.addText("Type 1 (Complete): 1→3→4→5  |  Type 2 (Incomplete): 1→(2*N)→3→4→5", {
    x: 5.0, y: 4.08, w: 4.4, h: 0.25,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: true
  });
  slide.addText("Type 2 loops through state 2 N times for slot-filling until all args are gathered", {
    x: 5.0, y: 4.35, w: 4.4, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "f8fafc"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

