// slide-04.js - Three Query Types
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Three Query Types Define Distinct State Trajectories'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Three Query Types Define Distinct State Trajectories", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Table header
  const tableX = 0.5;
  const tableY = 1.1;
  const colWidths = [1.2, 2.8, 4.0, 2.0];
  const rowH = 0.55;
  const headers = ["Query Type", "State Trajectory", "Description", "Example"];

  // Header row
  let currentX = tableX;
  headers.forEach((header, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: tableY, w: colWidths[i], h: rowH,
      fill: { color: theme.primary }
    });
    slide.addText(header, {
      x: currentX, y: tableY, w: colWidths[i], h: rowH,
      fontSize: 12, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
    currentX += colWidths[i];
  });

  // Data rows
  const data = [
    {
      type: "Type 1",
      trajectory: "1 → 3 → 4 → 5",
      desc: "Query contains all required arguments. No slot-filling needed.",
      example: "\"Find flights from NYC to LA on May 15\""
    },
    {
      type: "Type 2",
      trajectory: "1 → (2×N) → 3 → 4 → 5",
      desc: "Query lacks arguments. Slot-filling QA repeats N times until all fields gathered.",
      example: "\"Book a flight\" → [Which city?][Which date?]..."
    },
    {
      type: "Type 3",
      trajectory: "1 → 1",
      desc: "Functionality unavailable. Tool call must be rejected, stays in Initial state.",
      example: "\"Call my bank to transfer $1M\" → [Sorry, cannot help]"
    }
  ];

  const rowColors = [theme.accent, theme.secondary, theme.primary];

  data.forEach((row, rowIdx) => {
    const rowY = tableY + rowH * (rowIdx + 1);
    currentX = tableX;

    // Type cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: rowY, w: colWidths[0], h: rowH,
      fill: { color: rowColors[rowIdx] }
    });
    slide.addText(row.type, {
      x: currentX, y: rowY, w: colWidths[0], h: rowH,
      fontSize: 12, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
    currentX += colWidths[0];

    // Trajectory cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: rowY, w: colWidths[1], h: rowH,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 0.5 }
    });
    slide.addText(row.trajectory, {
      x: currentX, y: rowY, w: colWidths[1], h: rowH,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: true,
      align: "center", valign: "middle"
    });
    currentX += colWidths[1];

    // Description cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: rowY, w: colWidths[2], h: rowH,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 0.5 }
    });
    slide.addText(row.desc, {
      x: currentX + 0.1, y: rowY, w: colWidths[2] - 0.2, h: rowH,
      fontSize: 10, fontFace: "Calibri",
      color: theme.secondary,
      align: "left", valign: "middle"
    });
    currentX += colWidths[2];

    // Example cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: rowY, w: colWidths[3], h: rowH,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 0.5 }
    });
    slide.addText(row.example, {
      x: currentX + 0.1, y: rowY, w: colWidths[3] - 0.2, h: rowH,
      fontSize: 9, fontFace: "Calibri",
      color: theme.secondary, italic: true,
      align: "left", valign: "middle"
    });
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.6, w: 9, h: 1.2,
    fill: { color: theme.primary, transparency: 8 }
  });
  slide.addText("Key Insight", {
    x: 0.7, y: 3.7, w: 2, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true
  });
  slide.addText([
    { text: "Type 1 ", options: { bold: true, color: theme.accent } },
    { text: "and ", options: { color: theme.secondary } },
    { text: "Type 2 ", options: { bold: true, color: theme.secondary } },
    { text: "queries differ in whether slot-filling is required. ", options: { color: theme.secondary } },
    { text: "Type 3 ", options: { bold: true, color: theme.primary } },
    { text: "queries require the model to recognize out-of-scope requests and appropriately reject them.", options: { color: theme.secondary } }
  ], {
    x: 0.7, y: 4.05, w: 8.6, h: 0.65,
    fontSize: 12, fontFace: "Calibri"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "f8fafc"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

