const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Automatic Paired Trajectory Construction Without Human Labels'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Automatic Paired Trajectory Construction Without Human Labels", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("Each pair teaches a specific lesson about dialogue control", {
    x: 0.5, y: 0.88, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Learning lessons header
  const lessonY = 1.25;
  const lessonBoxW = 2.95;
  const lessonBoxH = 0.7;
  const lessonGap = 0.1;

  const lessons = [
    { title: "Redundant Slot-Filling", color: theme.accent },
    { title: "Slot Hallucination", color: theme.secondary },
    { title: "Tool Call Reject/Accept", color: theme.primary }
  ];

  lessons.forEach((lesson, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5 + i * (lessonBoxW + lessonGap), y: lessonY, w: lessonBoxW, h: lessonBoxH,
      fill: { color: lesson.color }
    });
    slide.addText(lesson.title, {
      x: 0.5 + i * (lessonBoxW + lessonGap), y: lessonY, w: lessonBoxW, h: lessonBoxH,
      fontSize: 13, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
  });

  // Dataset table
  const tableX = 0.5;
  const tableY = 2.1;
