  const tableX = 0.5;
  const tableY = 2.1;
  const colWidths = [0.7, 1.8, 2.3, 2.0, 0.9, 0.8];
  const rowH = 0.38;
  const headers = ["Query", "Chosen traj.", "Rejected traj.", "Learning", "Count", "Diff."];

