// slide-06.js - Benchmark Results
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'SFT + DiaTool-DPO Achieves Best Macro Average Across All Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("SFT + DiaTool-DPO Achieves Best Macro Average Across All Models", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("Evaluation on FunctionChat-Bench: Call, Completion, Slot, Relevance metrics", {
    x: 0.5, y: 0.78, w: 9, h: 0.28,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Main results table
  const tableX = 0.5;
  const tableY = 1.15;
  const colWidths = [1.3, 1.5, 0.75, 0.85, 0.75, 0.85, 0.9, 0.9];
  const rowH = 0.4;
  const headers = ["Model", "Method", "Call", "Compl.", "Slot", "Rel.", "Micro", "Macro"];

  // Header row
  let currentX = tableX;
  headers.forEach((header, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: currentX, y: tableY, w: colWidths[i], h: rowH,
      fill: { color: theme.primary }
    });
    slide.addText(header, {
      x: currentX, y: tableY, w: colWidths[i], h: rowH,
      fontSize: 10, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
    currentX += colWidths[i];
  });

  // Table data - best values highlighted
  const tableData = [
    // Prop.-8B
    { model: "Prop.-8B", method: "DiaTool-DPO", call: "0.314", compl: "0.700", slot: "0.833", rel: "0.609", micro: "0.575", macro: "0.614", modelRow: true },
    { model: "Prop.-8B", method: "SFT-only", call: "0.900", compl: "0.916", slot: "0.694", rel: "0.913", micro: "0.870", macro: "0.856", modelRow: false },
    { model: "Prop.-8B", method: "SFT+DTO", call: "0.886", compl: "0.929", slot: "0.833", rel: "0.826", micro: "0.884", macro: "0.868", modelRow: false, best: true },
    // Prop.-3.1B
    { model: "Prop.-3.1B", method: "DiaTool-DPO", call: "0.357", compl: "0.551", slot: "0.528", rel: "0.391", micro: "0.455", macro: "0.457", modelRow: true },
    { model: "Prop.-3.1B", method: "SFT-only", call: "0.771", compl: "0.817", slot: "0.750", rel: "0.826", micro: "0.790", macro: "0.791", modelRow: false },
    { model: "Prop.-3.1B", method: "SFT+DTO", call: "0.743", compl: "0.871", slot: "0.833", rel: "0.826", micro: "0.765", macro: "0.818", modelRow: false, best: true },
    // LLaMA-3-8B
    { model: "LLaMA-3-8B", method: "DiaTool-DPO", call: "0.029", compl: "0.449", slot: "0.056", rel: "0.261", micro: "0.205", macro: "0.199", modelRow: true },
    { model: "LLaMA-3-8B", method: "SFT-only", call: "0.843", compl: "0.957", slot: "0.639", rel: "0.826", micro: "0.844", macro: "0.816", modelRow: false },
    { model: "LLaMA-3-8B", method: "SFT+DTO", call: "0.857", compl: "0.929", slot: "0.917", rel: "0.913", micro: "0.905", macro: "0.904", modelRow: false, best: true }
  ];

  tableData.forEach((row, rowIdx) => {
    const rowY = tableY + rowH * (rowIdx + 1);
    currentX = tableX;

    // Highlight macro avg column specially
    const isMacroBest = row.best;
    const rowFill = row.modelRow ? (rowIdx % 3 === 0 ? theme.light : "FFFFFF") : "FFFFFF";

    const values = [row.model, row.method, row.call, row.compl, row.slot, row.rel, row.micro, row.macro];

    values.forEach((cell, colIdx) => {
      let fillColor = rowFill;
      let textColor = theme.primary;

      // Model column
      if (colIdx === 0 && row.modelRow) {
        fillColor = theme.secondary;
        textColor = "FFFFFF";
      }

      // Method column
      if (colIdx === 1) {
        if (row.method.includes("DiaTool")) fillColor = theme.accent;
        else if (row.method === "SFT-only") fillColor = theme.light;
        textColor = row.method.includes("DiaTool") || row.method === "SFT-only" ? theme.primary : theme.primary;
      }

      // Best macro - highlight entire row
      if (isMacroBest) {
        fillColor = theme.accent;
        textColor = "FFFFFF";
      }

      // Slot column - highlight high values
      if (colIdx === 4 && parseFloat(cell) >= 0.83) {
        // Already handled by best row
      }

      slide.addShape(pres.shapes.RECTANGLE, {
        x: currentX, y: rowY, w: colWidths[colIdx], h: rowH,
        fill: { color: fillColor },
        line: { color: theme.light, width: 0.5 }
      });

      slide.addText(cell, {
        x: currentX, y: rowY, w: colWidths[colIdx], h: rowH,
        fontSize: 9, fontFace: "Calibri",
        color: textColor,
        align: "center", valign: "middle"
      });
      currentX += colWidths[colIdx];
    });
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 10 }
  });
  slide.addText("Key Finding: SFT + DiaTool-DPO consistently achieves the highest Macro Avg across all model sizes", {
    x: 0.6, y: 4.92, w: 8.8, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });

  // Legend
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 4.55, w: 0.2, h: 0.2,
    fill: { color: theme.accent }
  });
  slide.addText("Best Macro Avg", {
    x: 7.25, y: 4.53, w: 1.2, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "f8fafc"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

