// slide-08.js - Key Takeaways
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: RL-Based Dialogue Control for Production TA-LLMs'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("RL-Based Dialogue Control for Production TA-LLMs", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Takeaway cards
  const takeaways = [
    {
      num: "1",
      title: "MDP Formulation Enables Systematic Trajectory Pairing",
      desc: "Defining 5 internal states and 3 query types allows automatic generation of chosen/rejected trajectory pairs without human annotation."
    },
    {
      num: "2",
      title: "DiaTool-DPO Consistently Improves Macro Average",
      desc: "Across all three model sizes (3.1B, 8B), SFT + DiaTool-DPO achieves the best balanced performance."
    },
    {
      num: "3",
      title: "Slot-Filling and Tool Rejection See Largest Gains",
      desc: "LLaMA-3-8B improves Slot accuracy by +43.5% and Relevance by +10.5% over SFT-only."
    },
    {
      num: "4",
      title: "DPO Complements Rather Than Replaces SFT",
      desc: "DiaTool-DPO-only performs poorly, confirming that DPO enhances but does not substitute supervised training."
    },
    {
      num: "5",
      title: "Approach is Language-Agnostic",
      desc: "Primary experiments in Korean, but method generalizes to English — opens broad applicability for production TA-LLMs."
    }
  ];

  const cardStartY = 1.4;
  const cardH = 0.7;
  const cardGap = 0.12;

  takeaways.forEach((item, i) => {
    const y = cardStartY + i * (cardH + cardGap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 9, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });

    // Accent bar on left
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 0.08, h: cardH,
      fill: { color: i % 2 === 0 ? theme.accent : theme.secondary }
    });

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.75, y: y + 0.15, w: 0.4, h: 0.4,
      fill: { color: i % 2 === 0 ? theme.accent : theme.secondary }
    });
    slide.addText(item.num, {
      x: 0.75, y: y + 0.15, w: 0.4, h: 0.4,
      fontSize: 14, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Title
    slide.addText(item.title, {
      x: 1.3, y: y + 0.08, w: 7.9, h: 0.3,
      fontSize: 13, fontFace: "Georgia",
      color: theme.primary, bold: true
    });

    // Description
    slide.addText(item.desc, {
      x: 1.3, y: y + 0.36, w: 7.9, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: theme.secondary
    });
  });

  // Bottom closing line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.15, w: 9, h: 0.03,
    fill: { color: theme.accent }
  });
  slide.addText("DiaTool-DPO opens a path to GPT-4o-level conversational tool use on smaller open-source models", {
    x: 0.5, y: 5.2, w: 9, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, italic: true, align: "center"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "f8fafc"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

